import{a as e}from"./rolldown-runtime-BWaJ3C7D.js";import{t}from"./view-BJpQNvy7.js";import{t as n}from"./Rect-BKrS3crf.js";import{_ as r,b as i,n as a,p as o,v as s,y as c}from"./index-CxwCIuUZ.js";import{n as l,t as u}from"./jsx-runtime-DApVmHJR.js";import{i as d,r as f}from"./Buttons-Kkl8mnsR.js";var p=JSON.parse(`[{"id":"minecraft-in-racket","repository":"https://github.com/jaron-cui/Minecraft-in-Racket","title":"Minecraft in Racket","date":"2021-09-01","status":"COMPLETED","technologies":["Racket (Intermediate Student Language)"],"features":["3D vector graphics","Infinite procedurally-generated terrain","Breakable and placeable blocks","Box-bounded collision and movement physics"],"paragraphs":["I started this project because I thought it would be interesting to implement a game suited to object-oriented programming in a heavily restricted functional programming language.","Some of the notable differences between ISL and Java (the language that the original game is implemented in) are ISL's lack of mutation, classes, and static typing. On the other hand, ISL includes first-class functions.","These distinctions meant that I did not have access to convenient data structures such as arrays, maps, and other constant-time access storage. So, in the process of designing the project, I had to implement immutable analogues. My replacement for Java's HashMap, for example, was tree structure bundled along with a comparison function, which could on average retrieve key/value pairs with a binary search."],"video":"https://youtube.com/embed/n3Io4oBeCn0?rel=0"},{"id":"worksheet-generator","repository":"https://github.com/jaron-cui/MathWorksheetGenerator","title":"Curricular Worksheet Generator","date":"2021-08-20","status":"COMPLETED","technologies":["Python","LaTeX"],"features":["Randomized problem generation in PDF format","Integer, decimal, and fractional addition, multiplication, and exponents","Answer key","Increased academic achievement by younger sister","Complaints from younger sister"],"paragraphs":["This worksheet generator is flexible and extendable. The process of adding new types of problems simply entails implementing a function which can produce randomized prompts and answers. Any number of these can be given to the worksheet generator, which itself will randomly choose one of these generators for each problem.","The program uses LaTeX to handle formatting. Since I found the existing LaTeX packages for Python to be unintuitive, I designed my own utilities for handling LaTeX document creation. These utilities have both generalized methods for ubiquitous document elements, such as headers, page numbers, paragraphs, and alignment, but also the ability to include raw LaTeX script and packages.","I have currently configured the program to generate math problems for the 6th grade level. I can add more types of problems and remove certain types as needed, and generate unlimited PDFs of unique worksheets without further modification."]},{"id":"mask-layout-generator","title":"Photolithographic Mask Layout Generator","date":"2021-06-24","status":"COMPLETED","technologies":["Python","KLayout"],"features":["GDSII format","Parameterizeable dimension constraints","Numbered mask grid layout generation","Multiple design variations within a single layout"],"paragraphs":["Over the summer of 2021, I joined a Binghamton University research project investigating a new type of nanoscale microphone. The project used the Cornell Nanoscale Facility in the prototyping and testing stage of the process, with the primary fabrication methods including photolithography, material deposition, and etching.","Photolithography is a process that uses ultraviolet light and patterned masks on silicon wafers to produce nanostructures. A mask is a glass plane that has been processed to have transparent and opaque sections, a scaled-up version of the desired pattern. By shining ultraviolet light through a lens onto a prepared silicon wafer, sections of the surface are chemically stabilized and the wafer can be moved to a chemical bath which removes layers from unexposed regions. The final result is a consistently reproducible silicon structure of a greatly reduced scale in relation to the original pattern mask.","In order to create a photolithographic mask, we must first design a layout digitally. However, since many variants of the nanostructures are needed for thorough testing of the properties of the design, the team was repeatedly manually adjusting the vertices and dimensions. This was a tedious and time-consuming process, so I took the initiative to implement a program which could parameterize the design.","This program allowed for adjustments to be made to the primary dimensions, such as lengths or quantities of features. Then, repeated sections and minor dimensions would be automatically recalculated and used to easily generate a new design layout.","The program outputs files in the GDSII (Graphic Design System) format, a file format commonly used for integrated circuit design. However, one of my team members is currently working to extend the program to output CAD files which can be used to simulate the physical design prior to real-world fabrication."]},{"id":"rust-physics","repository":"https://github.com/jaron-cui/rust-physics","title":"Circular-Entity Physics Simulator","date":"2022-03-06","status":"COMPLETED","technologies":["Rust","Nannou"],"clip":"https://drive.google.com/file/d/14uJ6_58N_Oi3TRHTWGL-zIMZR6YP8dl8/preview?loop=1","features":["Algebraically-resolved collisions","Gravity","Unlimited entity cap","Animated rendering"],"paragraphs":["I have always been intrigued by computer simulation. Previously, I've explored rectangular-bounded collisions with a variety of resolution methods. Here, I wanted to make a 'perfectly accurate' simulation free of the bugs commonly seen in physics simulations, such as clipping or unintuitive interactions.","=Typical Flaws of Simulated Collisions=","The simplest form of collision resolution subsumes incrementing the positions of objects, and then applying deflective collision forces on intersecting pairs. However, there are several unwanted behaviors that can emerge from this approach.","First, when the objects involved in what should be imminent collisions have a high relative velocity in comparison to their thickness, the collision may be missed altogether when there is no intersection during the frames preceding or following the hypothetical moment of collision.","Second, even during properly detected collisions, there is inaccuracy in the positions of the objects after collision, since in reality, most collisions do not occur exactly between two frames. If we simulated collisions continuously, they would occur at some point during a given frame.","Third, when a body collides several times between two frames, only the first collision will be accounted for.","=Addressing These Flaws=","The primary goal of this project is to avoid all of these inaccuracies and bugs. I selected circles over rectangles because of their directional symmetry. They would also serve well in a potential future project of simulating soft bodies composed of many rigid subunits.","To prevent the first and second issues, I decided to solve collisions algebraically. So, we can calculate the specific proportion of the frame at which a collision occurs. With this information, we can do frame-by-frame timesteps, but pretend as though we have infinite timesteps - we 'apply' the collision forces at the moment of impact and then increment the positions of the bodies accurate to the remaining time left in the frame.","For the third issue, we can run multiple collision checks per frame. In order to maximize the efficiency of this operation while ensuring all subframe collisions are accounted for, we only check for collisions for bodies that collided in the previous check. We repeat the check and resolution cycle until a check involves 0 bodies. (We should also add checks to safeguard against stable cycles of collisions, such as if a body is stuck oscillating between two other colliders)","With this line of deliberation, I am confident, as of now, that I have addressed all sources of simulation mistakes for 2D collisions."]},{"id":"frog-games","repository":"https://github.com/jaron-cui/frames-backend","title":"Multiplayer Game Site","date":"2022-04-03","status":"ON_HOLD","technologies":["TypeScript","React","Spring Boot","Websocket"],"features":["Real-time multiplayer games with friends","REST and websocket frontend-backend communication","Polished in-game animations","Player statistics"],"paragraphs":["It is not uncommon for my friends and I to want to play short multiplayer games with each other. However, sometimes there are no good options for particular games online - they might demand money or be covered in ads, if they exist at all. The only free option we could find online for Mancala is text-based!","So, fine, I'll do it myself!","We'll make Mancala, and checkers, minesweeper but competitive, connect X=?, and whatever else we feel like playing!","Coming soon... eventually!"]},{"id":"image-editor","repository":"https://github.com/jaron-cui/CS3500-HW5","title":"Image Editor Application","date":"2021-06-07","status":"COMPLETED","technologies":["Java","Swing"],"features":["Command-line operation","GUI mode","Scriptable operations","Transparency","Filter and linear image transformations","Resizing","Image layers","Project save and load","File export"],"paragraphs":["An assignment from the course CS3500: 'Object-Oriented Design'.","This image editor has both a CLI and a GUI mode, both of which grant the user access to all image and project operations. These include image scaling and layering, color manipulation including grayscaling, saturation/brightness adjustment, and themed color scales. There are also filter operations such as sharpening and blurring.","Since we had already implemented a CLI, we also added scripting capabilities for which scripts can be stored in text files and executed. Repetitive or complex actions can thus be recorded for straightforward reuse."]},{"id":"maze-generator","title":"Maze Generator and Visualizer","date":"2021-04-15","status":"COMPLETED","technologies":["Java"],"clip":"https://drive.google.com/file/d/1jYfMvI46QrOYmRXe764Nlq3pmSBrfTjS/preview","features":["Orthogonal maze generation","Hexagonal maze generation","Start/end distance color gradient option","Breadth-first and depth-first maze solver","Interactable game mode","Dynamic directional controls with angular tolerance"],"paragraphs":["An assignment from the course CS2510: 'Fundamentals of Computer Science II (Accelerated)'.","Mazes can either be composed of traditional square segments, where corridors and turns are orthogonal, or with hexagonal tiles resembling a beehive where each node could connect to a maximum of 6 others. We generate a maze with a single correct path using Prim's algorithm.","Maze generation and automatic solving can both be animated step-by-step. In the case of manual solving, where the user controls a 'player' that sits on a particular node, navigation can be done with the WEADZX keys (note that these keys form a hexagon around the 'S' key, which correspond to their intending direction of movement).","When the user presses one of the movement keys, then if there is an open pathway within an angular threshhold of the intended direction, they will move to the node at the end of that pathway. This allows the same control scheme to be compatible with both the square and hexagon-tiled mazes, as well as variations such as ones that give a randomized offset to each node."]},{"id":"seam-carver","title":"Image Seam Carver","date":"2021-03-24","status":"COMPLETED","technologies":["Java"],"clip":"https://drive.google.com/file/d/1rM-qhn94SdljSHCZszBRe20AeS5wjC2P/preview","features":["Vertical and horizontal seam carving","Image import/export","Animated seam carving","Carve pausing","Carve undo/reversal"],"paragraphs":["An assignment from the course CS2510: 'Fundamentals of Computer Science II (Accelerated)'.","A simple image seam-carving application for scaling down images in a way that attempts to preserve the most important features."]},{"id":"get-rect","title":"get_rect(): 2D Sandbox Duel!","date":"1600-01-01","status":"COMPLETED","technologies":["Python","pygame"],"features":["2D box-bounded physics","Destructible grid-based terrain","Animated entities","Ranged and melee weapons","Explosions!","Sound effects!","Logically following, fireworks and dynamite!"],"paragraphs":["My first game development project in Python, using pygame for the main game loop logic and custom implementations for all game mechanics.","The name of the game comes from an essential function included with pygame, 'get_rect()', which retrieves the bounding box of a rendered image. I thought this would be a fun reference to the then-popular taunt, 'Get wrecked!'.","This was one of my earlier experiments with 2D physics, toying with simple box-bounded intersection collisions. All entities in the game have a mass and velocity, and can therefore be knocked around by players and explosions, which I think makes the game quite enjoyable even without the PVP aspect."]},{"id":"allchemical","title":"Allchemical","date":"2022-07-17","status":"ON_HOLD","technologies":["C++","SFML"],"clip":"https://drive.google.com/file/d/1ReWX4WrXyg7f0TGS8U7dbxFbKpKYp-zA/preview","features":["Spring physics!"],"paragraphs":["An exploratory experiment that borrows basic physics logic from my previous project in Rust, the eventual goal being the simulation of larger-scale materials that may be liquids, gases, or solids which will be able to 'react' to form different compounds.","An important concept in this simulation will be 'bonds', which I'm implementing to behave akin to physical springs attached at points on atomic surfaces. Since I much prefer experimenting to reading dense articles explaining physics, I've simply taken Hooke's law of springs where F = -kx and applied it to the stretching, bending, and deviant rotation of imaginary 'springs' to achieve a visually appealing result. I'm not certain if this application is accurate to the behavior of real springs, though.","You can see the very early progress I've achieved above, where the GREEN 'atoms' have their rotational axes indicated with RED lines extending from their centers, and bonded atom pairs are connected with BLUE lines.","Eventually, the presence of, absense of, and the properties of these bonds will distinguish the physical phases of materials. Other than this, I will also be able to use these bonds to simulate threads and soft bodies."]},{"id":"finite-state-automata","repository":"https://github.com/jaron-cui/finite-state-automata","title":"State Machine Simulator","date":"2022-07-24","status":"COMPLETED","technologies":["Python","Graphviz"],"features":["Determinate Finite State Machines","Nondeterminate Finite State Machines","NFA to DFA conversion","State machine simplification","Graphviz rendering of state machine diagrams"],"paragraphs":["My 2022 Summer 2 semester courses include Theory of Computation, where one of the topics covered is state machines/automata. I'm learning about determinate and nondeterminate finite state automata, pushdown automata, and Turing machines.","This project is to put into implementation some of the concepts I've learned about, including NFA to DFA conversion, state machine unions, and regular expression equivalency."],"gallery":[{"type":"image","description":"Instantiating an NFA, then converting it to an equivalent DFA","link":"https://drive.google.com/file/d/1QMB-Dw8Lf-U1raDzSS_p_09l71cFe7V2/view?usp=sharing"},{"type":"image","description":"The NFA produced and rendered by the code in the previous slide","link":"https://drive.google.com/file/d/1C3buexJpl88BUvV1sMR7vK5Mr4xXAiP4/view?usp=sharing"},{"type":"image","description":"The DFA produced from running '.to_dfa()' on the NFA","link":"https://drive.google.com/file/d/1PUpvptGBBxC7oxMV2jympMRiGiOhVyT7/view?usp=sharing"}]},{"id":"wordle","repository":"https://github.com/jaron-cui/jaron-cui.github.io/blob/master/src/page/extraneous/Wordle.tsx","title":"Serverless Wordle with Unlimited Daily Games","date":"2023-03-17","status":"COMPLETED","technologies":["TypeScript","React"],"features":["Unlimited unique games per day","Game solution encoded in URL","Onscreen color-coded keyboard"],"paragraphs":["Check it out at https://jaron-cui.github.io/#/wordle","My friends and I will often do NYT daily games and post our scores in the group chat. It's a nice common activity to have even when we're too busy to hang out.","However, Wordle is limited to a single global game each day. I decided to make a version with an unlimited amount of unique games that are still shareable with friends, since the fun comes from seeing who can guess the word in the fewest guesses.","Since creating some kind of database would have been overkill, I instead encoded the solution for each game in the URL, which is unreadable to humans but enables serverless game sharing."]},{"id":"minecraft-in-c++","repository":"https://github.com/jaron-cui/minecraft-in-cplusplus","title":"Minecraft in C++","date":"2023-11-18","status":"COMPLETED","technologies":["C++","OpenGL","SDL2"],"features":["OpenGL rendering","Infinite 3D Perlin noise terrain generation","Original physics engine","Day/night cycle"],"paragraphs":["My previous Minecraft clone in Racket ISL was a test of my ability to implement a complex project in a highly limited language. This project is an experiment in designing an efficient implementation in a traditional programming language with a developed toolset.","Consequently, the performance, accuracy, power, and feature set of this version far exceeds its predecessor.","With a new physics engine, rendering system, and a sophisticated terrain generation system, this project is an excellent foray into C++ and OpenGL.","Eventually, I hope to add other entities, inventory, and multiplayer to the game."],"video":"https://youtube.com/embed/H6CSRfh5ud8?rel=0"}]`),m=[{id:`ta-cs2500`,title:`Teaching Assistant for CS2500 (Accelerated)`,organization:`Northeastern University`,timeframe:{semesters:[`Fall 2021`]},paragraphs:[`My first teaching assistant position at Northeastern. For the course CS2500 (Fundamentals of Computer Science I Accelerated), taught by Amal Ahmed and Benjamin Lerner.`]},{id:`ta-cs3000`,title:`Teaching Assistant for CS3000`,organization:`Northeastern University`,timeframe:{semesters:[`Summer II 2022`]},paragraphs:[`A position as one of three teaching assistants for CS3000 (Algorithms and Data Structures), taught by Greg Aloupis.`]},{id:`coop-poweradvocate`,title:`Software Development Co-op`,organization:`Wood Mackenzie (PowerAdvocate)`,timeframe:{start:`2022-01-04`,end:`2022-07-01`},projects:[`poweradvocate-api`,`poweradvocate-energy-product`],paragraphs:[`Wood Mackenzie develops products and services focused on data analytics and forecasting for energy markets. During this co-op, I gained a professional level of expertise working with TypeScript, Node, React, and Java.`,`I first worked on a team of 7 focused on addressing dependency vulnerabilities in a large Java codebase. This later shifted to migrating the database from OracleDB to PostgreSQL, which we did by porting the schema and modifying SQL using the AWS Schema Conversion Tool.`,`Next, I joined a newly formed team tasked with building an API for an existing service, the purpose of which was to serve large datasets accessible through the main customer platform. The API was to include typical request-response REST endpoints of limited size as well as a set of endpoints for asynchronously retrieving data exceeding 100,000 rows. My responsibility was to build the API backend itself. We selected the Spring framework for this task, which we used to implement endpoints under the OData v4.0 Protocol. I paired with several full-time employee to design and code the backend.`,`Throughout development, we had regular code reviews with the other members of the team and solidifed the deliverability requirements with our product owner. For example, we wrote tests in Node and automated them using GitLab Pipelines and Docker.`,`After we finished reviewing and deploying the finished product via Docker, I joined a team in a different business unit developing an infrastructure project management platform. We wrote the frontend in React and TypeScript, which interacted with a GraphQL backend. I worked on creating new pages and adding functionality to the backend as required. I often did this in pairs with other developers. We commonly held refinement meetings to review and prioritize the project requirements, and underwent retroactive evaluations to improve our workflow moving forward.`,`Overall, this was an excellent co-op experience. I felt welcomed and trusted in the development process and team bonding activities likewise. I contributed to the development of currently-deployed products and influenced many choices made during the process. Looking forward, along with the major upgrade to my skillset, I've gained many personal connections which I value greatly.`]}],h=u();function g(e){return(0,h.jsx)(h.Fragment,{children:(0,h.jsx)(`iframe`,{id:`video`,src:e.link,allow:`autoplay`,loading:`lazy`,width:e.width||`768`,height:e.height||`432`})})}var _=e(l(),1);function v({media:e}){let[t,n]=(0,_.useState)(0),i=(0,_.useRef)([]),[a,s]=(0,_.useReducer)(e=>e+1,0),c=r=>()=>{let i=o(t+r,e.length);n(i)};return(0,_.useEffect)(()=>{i.current=e.map(e=>(0,h.jsx)(`img`,{src:r(e.link),style:{objectFit:`contain`,width:`100%`}}))},[]),(0,h.jsxs)(`div`,{style:{height:`300px`,width:`100%`,display:`flex`,justifyContent:`center`},children:[(0,h.jsx)(f,{direction:`left`,onClick:c(-1)}),(0,h.jsx)(d,{title:e[t].description,leaveDelay:0,children:(0,h.jsx)(`div`,{style:{display:`flex`,backgroundColor:`#999999`,height:`100%`,width:`max(50%, 700px)`},children:(0,h.jsx)(`img`,{src:r(e[t].link),decoding:`async`,style:{objectFit:`contain`,width:`100%`}})})}),(0,h.jsx)(f,{direction:`right`,onClick:c(1)})]})}function y(){return(0,h.jsxs)(`div`,{children:[(0,h.jsx)(`h3`,{children:`Building a Personal Marimba`}),s((0,h.jsx)(g,{link:`https://www.youtube.com/embed/fnrT9LNhCe0?si=vfL1YcFmCFj8Zx4u&loop=1&rel=0`})),(0,h.jsx)(`h4`,{children:`Impetus`}),(0,h.jsx)(`p`,{children:`One my younger sisters plays the marimba in the high school band. Marimbas are essentially full wooden pianos, costing $4,000 for one on the cheaper side. So every time she wants to practice, she needs to stay after school when a teacher is present to unlock the band room. That is, until I decided to build one for her for around $300 in material costs.`}),(0,h.jsxs)(a,{children:[(0,h.jsxs)(i,{children:[(0,h.jsx)(`img`,{src:`project/marimba/living-room.jpg`,alt:`Installing eye hooks`,width:`41%`}),(0,h.jsx)(`img`,{src:`project/marimba/frame.jpg`,alt:`Placing keys`,width:`59%`})]}),(0,h.jsx)(i,{children:(0,h.jsxs)(c,{children:[(0,h.jsx)(`img`,{src:`project/marimba/living-room.jpg`,alt:`Installing eye hooks`,width:`100%`}),(0,h.jsx)(`img`,{src:`project/marimba/frame.jpg`,alt:`Placing keys`,width:`100%`})]})})]}),(0,h.jsx)(`h4`,{children:`Research`}),(0,h.jsx)(`p`,{children:`My prior knowledge of marimbas came essentially just from what I pictured a marimba to be - a set of suspended wooden blocks cut to lengths inversely proportional to their pitch. A few internet searches gave me the knowledge I needed to start: how to make a block of wood have a lower or higher pitch.`}),(0,h.jsx)(`p`,{children:`The two primary factors that affect the pitch of a wooden key are its length and its rigidity. A longer key vibrates at a lower frequency (it takes more time for a vibration to travel the length), and a more rigid key vibrates at a higher frequency (stronger restoring force). These factors are controlled in practice by cutting the key to a specific length and carving wood out of its center (the removal of material reduces rigidity faster than mass). Thus, you first cut a wooden block such that it has a higher pitch than desired, and then carve to incrementally reduce it.`}),(0,h.jsx)(`p`,{children:`In order to minimize interference with sound quality, the complete keys are strung on taut cables.`}),(0,h.jsx)(`h4`,{children:`Proof-of-Concept Experiments`}),(0,h.jsx)(`p`,{children:`My first action was to create a minimal test setup to prove the viability of the marimba. I purchased a 1.5 x 0.75 x 72 inch red oak plank, eye hooks, and a bundle of paracord from Lowes. Then, I sawed two blocks off the plank, 7 and 14 inches long. These were meant to represent the aesthetically shortest and longest keys I wanted to install on the marimba. Placing these keys on the cables of a test rig, I struck them and confirmed that red oak keys with lengths in the interval [7, 14] inches could produce all the semitones required for a four-octave marimba from C5 to C9.`}),(0,h.jsx)(`p`,{children:`I have never done extensive woodwork. But I figured that a chisel and mallet should be sufficient for carving the keys. Taking the 14 inch test key, I incrementally chiseled a parabolic impression in the center, striking it against the ground occasionally to test its pitch. When it was close to C5 but still sharp, I placed it on cables and sprinkled sawdust over it. By repeatedly tapping it, the sawdust started collecting in two piles at opposite ends, indicating the location of the vibrational nodes. I drilled holes through the sides here for stringing cable. This was meant to minimize any dampening that might come from the suspension substrate. After, I chiseled a bit more until the pitch was no longer sharp.`}),(0,h.jsx)(`p`,{children:`Next, I applied coats of wood stain and polyacrylic seal to represent the final look of the key. With this, I had produced a single finished key and demonstrated the process. I discovered that neither the drilled suspension holes nor the sealing coats noticeably altered the pitch.`}),(0,h.jsx)(`h4`,{children:`Making the Keys`}),(0,h.jsx)(`p`,{children:`I planned for the marimba to have 29 white keys and 20 black keys (white or black referring to the role of the key as on a piano), meaning I would have to make 49 individual keys. Each minute spent per key would mean nearly an extra hour total, and making the test key from start to finish took around an hour of labor. So, I invested half an hour planning how to streamline the process. I ended up cutting, chiseling, drilling, testing, and painting keys in large batches, reducing the per-key time to about 12 minutes. Eliminate context switching!`}),(0,h.jsxs)(a,{children:[(0,h.jsxs)(i,{children:[(0,h.jsxs)(c,{children:[(0,h.jsx)(i,{children:(0,h.jsx)(`img`,{src:`project/marimba/chisel-setup.jpg`,alt:`Chiseling setup`,width:`100%`})}),(0,h.jsx)(i,{children:(0,h.jsx)(`img`,{src:`project/marimba/chisel-pile.jpg`,alt:`Chiseled keys`,width:`100%`})}),(0,h.jsx)(i,{children:(0,h.jsx)(`img`,{src:`project/marimba/drill-pile.jpg`,alt:`Drilled keys`,width:`100%`})}),(0,h.jsx)(i,{children:(0,h.jsx)(`img`,{src:`project/marimba/paint-pile.jpg`,alt:`Stained and sealed keys`,width:`100%`})})]}),(0,h.jsxs)(i,{children:[(0,h.jsx)(g,{width:`60%`,link:`https://www.youtube.com/embed/sWjNLyihTdY?si=QHj87NXSSPhOk--n&loop=1&rel=0`}),(0,h.jsx)(g,{width:`40%`,link:`https://www.youtube.com/embed/7_DKkGn3H5M?si=kahAtw0BHCaV0wDw&loop=1&rel=0`})]})]}),(0,h.jsx)(i,{children:(0,h.jsxs)(c,{children:[(0,h.jsx)(g,{link:`https://www.youtube.com/embed/sWjNLyihTdY?si=QHj87NXSSPhOk--n&loop=1&rel=0`}),(0,h.jsx)(g,{link:`https://www.youtube.com/embed/7_DKkGn3H5M?si=kahAtw0BHCaV0wDw&loop=1&rel=0`}),(0,h.jsx)(`img`,{src:`project/marimba/chisel-setup.jpg`,alt:`Chiseling setup`,width:`100%`}),(0,h.jsx)(`img`,{src:`project/marimba/chisel-pile.jpg`,alt:`Chiseled keys`,width:`100%`}),(0,h.jsx)(`img`,{src:`project/marimba/drill-pile.jpg`,alt:`Drilled keys`,width:`100%`}),(0,h.jsx)(`img`,{src:`project/marimba/paint-pile.jpg`,alt:`Stained and sealed keys`,width:`100%`})]})})]}),(0,h.jsx)(`h4`,{children:`Building the Stand`}),(0,h.jsx)(`p`,{children:`I designed the marimba to have a lower keyboard and an upper keyboard. The lower keyboard is for the white keys, and the upper keyboard is for the black keys. Each keyboard consists of two wooden rails down the length of the marimba, fixed together by cross beams. One of the rails is parallel to the central axis of the marimba, whereas the other is angled to acommodate the gradually increasing lengths of the keys. Keys are suspended between consecutive pairs of eye hooks on the rails.`}),(0,h.jsx)(`p`,{children:`The keyboards sit atop a four-wheeled rectangular stand. I designed the stand such that it could be made out of the 2.5 and 1.5 inch wide, 0.75 inch thick red oak and maple planks I had already been using for the keys. Caster wheels are screwed to the bottom four corners.`}),(0,h.jsx)(`p`,{children:`Finally, I strung the keys and mounted the keyboards. The marimba was complete!`}),(0,h.jsxs)(a,{children:[(0,h.jsxs)(i,{children:[(0,h.jsxs)(i,{children:[(0,h.jsx)(`img`,{src:`project/marimba/install-eyehooks.jpg`,alt:`Installing eye hooks`,width:`25%`}),(0,h.jsx)(`img`,{src:`project/marimba/place-keys.jpg`,alt:`Placing keys`,width:`25%`}),(0,h.jsx)(`img`,{src:`project/marimba/thread-setup.jpg`,alt:`Threading setup`,width:`25%`}),(0,h.jsx)(`img`,{src:`project/marimba/thread-keys.jpg`,alt:`Threading keys`,width:`14%`})]}),(0,h.jsxs)(i,{children:[(0,h.jsx)(`img`,{src:`project/marimba/frame-plan.jpg`,alt:`Planning the frame`,width:`40%`}),(0,h.jsx)(`img`,{src:`project/marimba/frame-setup.jpg`,alt:`Assembly area`,width:`18.5%`}),(0,h.jsx)(`img`,{src:`project/marimba/frame-clamp.jpg`,alt:`Assembling the frame`,width:`18.5%`}),(0,h.jsx)(`img`,{src:`project/marimba/frame-screw.jpg`,alt:`Screwing the frame together`,width:`18.5%`})]})]}),(0,h.jsx)(i,{children:(0,h.jsxs)(c,{children:[(0,h.jsx)(`img`,{src:`project/marimba/install-eyehooks.jpg`,alt:`Installing eye hooks`,width:`100%`}),(0,h.jsx)(`img`,{src:`project/marimba/place-keys.jpg`,alt:`Placing keys`,width:`100%`}),(0,h.jsx)(`img`,{src:`project/marimba/thread-setup.jpg`,alt:`Threading setup`,width:`100%`}),(0,h.jsx)(`img`,{src:`project/marimba/thread-keys.jpg`,alt:`Threading keys`,width:`100%`}),(0,h.jsx)(`img`,{src:`project/marimba/frame-setup.jpg`,alt:`Assembly area`,width:`100%`}),(0,h.jsx)(`img`,{src:`project/marimba/frame-plan.jpg`,alt:`Planning the frame`,width:`100%`}),(0,h.jsx)(`img`,{src:`project/marimba/frame-clamp.jpg`,alt:`Assembling the frame`,width:`100%`}),(0,h.jsx)(`img`,{src:`project/marimba/frame-screw.jpg`,alt:`Screwing the frame together`,width:`100%`})]})})]}),(0,h.jsx)(`h4`,{children:`Conclusion`}),(0,h.jsx)(`p`,{children:`The marimba turned out to have great sound and a sturdy construction. It now sits in our living room for my sister to practice on. The entire process took two and a half weeks, but the result will likely exist for decades. I consider this to be a pretty good way to have spent my winter break!`})]})}var b=[{legacy:!1,id:`marimba`,title:`Marimba`,date:`2026-01-12`,status:`COMPLETED`,technologies:[`Woodwork`,`Music`,`Chiseling`],page:y},{legacy:!1,id:`cdit-planning`,repository:`https://github.com/jaron-cui/nwm-planning`,title:`Planning with World Models`,date:`2025-12-02`,status:`COMPLETED`,technologies:[`Python`,`PyTorch`,`Conditional Diffusion Transformer`,`Variational Autoencoder`],page:e=>(0,h.jsxs)(`div`,{children:[(0,h.jsx)(`h4`,{children:`Summary`}),(0,h.jsx)(`p`,{children:`I train a CDiT-based world model on a topographical navigation environment and demonstrate that it can be used for action planning via probing with stochastically sampled actions. We effectively explore the terrain virtually. This may be useful in applications where we must do zero-shot planning on novel terrain.`}),(0,h.jsx)(`h4`,{children:`Motivation`}),(0,h.jsxs)(`p`,{children:[`My Computer Vision class, taught by Saining Xie, had a guest speaker YuTong Bai. Her recent work, `,(0,h.jsx)(`i`,{children:`Whole-Body Conditioned Egocentric Video Prediction`}),`, trained an autoregressive Conditional Diffusion Transformer (CDiT) on egocentric human video with pose data to serve as a World model capable of predicting future visual states given past states and human pose actions. In essence, the CDiT developed an understanding of the visual dynamics of human motion without any explicit labeling of objects in the world.`]}),(0,h.jsxs)(`p`,{children:[`World models seem to be a tentatively useful tool. On one hand, the perfect world model captures dynamics to the point that it is essentially a hyperrealistic simulation. A hyperrealistic simulation would be immensely useful for robotics applications. The most common training paradigm for robotics is domain-specific data collection. This is expensive and generally nongeneralizable! Every new task we want to train a robot on requires a whole new set of data collection for that task. But a performant and accurate simulation that captures `,(0,h.jsx)(`i`,{children:`general`}),` dynamics theoretically encodes the information needed for any physical task. AI world models also have the advantage over simulations in that they will continuously get better with additional training data, whereas simulations need to be manually extended and improved. Of course, it is easier said than done to train a good world model.`]}),(0,h.jsx)(`p`,{children:`I became interested in seeing whether I could use world models to perform zero-shot planning on robotics tasks. I settled on navigation and manipulation as target domains of robotics.`}),(0,h.jsx)(`h4`,{children:`Implementation`}),(0,h.jsx)(`p`,{children:`In Bai's original paper, the environment consisted of egocentric navigation in the real world. One observation I have regarding world models is that you can either use more informative state data or have a more powerful model. Egocentric navigation uses a relatively uninformative observation (just a single first person view) and a very powerful world model (capable of extrapolating entire 3D scenes from single first person views). I decided to build a simpler environment from scratch to accommodate my sparser computational resources. I would use simpler dynamics with a more informative observation to cut down on uncertainty. The environment I settled on is a top-down topographic view of procedurally generated mountainous terrain, centered on the position of the actor. Actions are XY displacements of the actor, which can be obstructed by impassable terrain above a certain altitude.`}),(0,h.jsx)(`div`,{style:{paddingBottom:`40px`},children:s((0,h.jsx)(g,{link:`https://drive.google.com/file/d/1GAiFphsIMMTBZVtHWaG9WQcH3iZXq-ab/preview`}))}),(0,h.jsx)(`p`,{children:`We can use this model for planning by algorithmically probing it with stochastically-sampled actions. The resulting directed acyclic graph grows until the desired end state is found. This means that our probing algorithm and world model can produce a sequence of actions to move from a starting state to a goal state, where the only inputs are an image of the start state and an image of the goal state. Isn't that amazing? The world model can simulate the dynamics of the world without really "knowing" what it's simulating. It has no conception of mountains; it has simply learned that high topographic values indicate impassability. We determine goal proximity with a distance function trained to predict the navigational distance between two images.`}),(0,h.jsx)(`h4`,{children:`Results`}),(0,h.jsx)(`p`,{children:`The trained CDiT has captured the dynamics of the environment accurately enough that planned trajectories work when deployed in the real environment. Below, we have an example of a start and goal image pair with an obstacle between them.`}),(0,h.jsx)(`div`,{style:{paddingBottom:`40px`},children:(0,h.jsxs)(a,{children:[s((0,h.jsx)(`img`,{width:`30%`,src:`project/cdit-planning/obstruction-navigation.png`})),s((0,h.jsx)(`img`,{width:`100%`,src:`project/cdit-planning/obstruction-navigation.png`}))]})}),(0,h.jsx)(`p`,{children:`The algorithm is able compose a sequence of stochastically sampled actions that the world model believes reaches the goal state. Below, we have the expected trajectory decoded with the VAE from the CDiT latents (this video is entirely CDiT output!), and then the trajectory produced by rolling out the action sequence in simulation.`}),(0,h.jsx)(`div`,{style:{paddingBottom:`40px`},children:(0,h.jsxs)(a,{children:[s((0,h.jsxs)(h.Fragment,{children:[(0,h.jsx)(`img`,{width:`15%`,src:`project/cdit-planning/obstructed_planned_trajectory.gif`}),(0,h.jsx)(`img`,{width:`15%`,src:`project/cdit-planning/obstructed_mujoco_rollout.gif`})]})),s((0,h.jsxs)(h.Fragment,{children:[(0,h.jsx)(`img`,{width:`100%`,src:`project/cdit-planning/obstructed_planned_trajectory.gif`}),(0,h.jsx)(`img`,{width:`100%`,src:`project/cdit-planning/obstructed_mujoco_rollout.gif`})]}))]})}),(0,h.jsx)(`p`,{children:`Here, we have a longer-form zero-shot trajectory planning example where the algorithm is given a sparse demonstration of the desired path. The algorithm plans the actions between each consecutive pair of snapshots and produces a sequence of actions that successfully reproduce the path in simulation.`}),(0,h.jsxs)(`div`,{style:{paddingBottom:`40px`},children:[s((0,h.jsx)(g,{link:`https://drive.google.com/file/d/1wcE78WWiQbHiQ5uxpbOBsvp_Xs2_y_Bb/preview`,width:`320`,height:`320`})),s((0,h.jsx)(g,{link:`https://drive.google.com/file/d/1p31Emkaj0W9u8ygOV_QpUWbFPzzRHuVK/preview`,width:`320`,height:`320`}))]}),(0,h.jsx)(`p`,{children:`The most striking feature about extended world model exploration is how self-consistent the predicted world is. When rolling out a random walk of 200 actions in this world model, the shapes of the terrain look very close to the initial shapes. I suppose that one strength of diffusion models is that they are explicitly trained to refine structure from noise, making them considerably robust to accumulated error. Normally, an input passed through a recurrent model 200 times would end with a great deal of error.`})]})},{legacy:!1,id:`neural-evolution-v1`,repository:`https://github.com/jaron-cui/neural-evolution`,title:`Evolution of Biorealistic Neural Development`,date:`2025-04-16`,status:`COMPLETED`,technologies:[`Python`,`PyTorch`,`MLP`],page:e=>(0,h.jsxs)(`div`,{children:[(0,h.jsx)(`h4`,{children:`Summary`}),(0,h.jsxs)(`p`,{children:[`I attempt to build biorealistic neural networks composed of highly parameterized neurons with latent states and genetically-defined behavioral projections meant to enable the nuanced chemical behaviors of real neurons to be emulated. Specimens start from a single neuron and undergo self-regulated mitosis. After 70 generations of evolutionary selection from mutated populations, I find that the neural population can reach a stable size. I have not tried to evolve useful firing behavior because since my last work on the project, I've learned more about neuroscience and have concluded that there are too many shortcomings with this model. I plan to build a revised version. The main flaws are that:`,(0,h.jsxs)(`ol`,{children:[(0,h.jsx)(`li`,{children:`This simulation uses binary firing states, when a rate-coded firing state would have superior representational capacity.`}),(0,h.jsx)(`li`,{children:`The quadratic growth of inter-neuron connection calculations is incredibly inefficient. The version 2 of this project will seek to impose structural constraints that make connection checking significantly sparser.`})]})]}),(0,h.jsx)(`div`,{style:{paddingBottom:`40px`},children:(0,h.jsxs)(a,{children:[s((0,h.jsx)(`img`,{width:`50%`,src:`project/neural-evolution-v1/neural-evolution-specimen.gif`})),s((0,h.jsx)(`img`,{width:`100%`,src:`project/neural-evolution-v1/neural-evolution-specimen.gif`}))]})}),(0,h.jsx)(`h4`,{children:`Motivation`}),(0,h.jsxs)(`p`,{children:[`What we call "neural networks" are, in my opinion, only `,(0,h.jsx)(`i`,{children:`very`}),` loosely based on how real neural networks work. Consider a sequence of fully-connected layers interspaced with ReLU activations. The main biologically-inspired components here are the activation functions and integration of inputs. The activation function is based on action potentials, and the integration emulate the excitatory and inhibitory signals from other neurons.`]}),(0,h.jsx)(`p`,{children:`However, real neurons aren't arranged in neat layers, they don't behave like stateless, timeless functions, and their connections aren't static. A real neural network brings to mind an interwoven web of connections where timing matters and occasional rewiring encodes information. Inscrutable chemical interactions and signals influence the network. And most dramatically, the entire network started as a handful of cells undergoing mitosis.`}),(0,h.jsx)(`p`,{children:`I want to try and simulate a biorealistic neural network that starts as one cell and recursively divides to grow into a cloud of neurons. I want these neurons to have action potentials, be able to initiate mitosis or apoptosis based on external and internal factors, and communicate complex chemical messages to one another.`}),(0,h.jsx)(`h4`,{children:`Neuron Parameters`}),(0,h.jsx)(`p`,{children:`The basic neural unit needs a considerable set of parameters to exhibit the desired behaviors. Here is a diagram summarizing the parameters that I have settled on for this project.`}),(0,h.jsx)(`div`,{style:{paddingBottom:`40px`},children:(0,h.jsxs)(a,{children:[s((0,h.jsx)(`img`,{width:`50%`,src:`project/neural-evolution-v1/data-representation.png`})),s((0,h.jsx)(`img`,{width:`100%`,src:`project/neural-evolution-v1/data-representation.png`}))]})}),(0,h.jsx)(`h4`,{children:`Genome`}),(0,h.jsx)(`p`,{children:`I mentioned before that I want to allow complex evolving and reactive cell behaviors that emulate the nuanced chemical interactions of real neurons. The way I accomplish this is by evolving the functional parameters and hidden state of each neuron with a set of MLPs whose weights I designate as part of the genome. For example, there is a parameter derivation MLP that projects the internal and external state of a neuron into its activation threshold, signal strength, and hormone emission for the current simulation tick. This allows the neuron to rewire itself in response to various factors. There is the passive update MLP that evolves the hidden state each tick, the active update MLP that evolves the hidden state upon firing, and then there are the MLPs that output the connection strength between any two neurons and determine the hidden state of daughter cells upon mitosis. This system of genetically-defined projections from state to behavior is intended to allow for complex dynamics akin to those in real biology to develop.`}),(0,h.jsx)(`div`,{style:{paddingBottom:`40px`},children:(0,h.jsxs)(a,{children:[s((0,h.jsx)(`img`,{width:`50%`,src:`project/neural-evolution-v1/genome.png`})),s((0,h.jsx)(`img`,{width:`100%`,src:`project/neural-evolution-v1/genome.png`}))]})}),(0,h.jsx)(`h4`,{children:`Simulation Loop`}),(0,h.jsx)(`div`,{style:{paddingBottom:`40px`},children:(0,h.jsxs)(a,{children:[s((0,h.jsx)(`img`,{width:`50%`,src:`project/neural-evolution-v1/code.png`})),s((0,h.jsx)(`img`,{width:`100%`,src:`project/neural-evolution-v1/code.png`}))]})}),(0,h.jsx)(`h4`,{children:`Visualization`}),(0,h.jsx)(`p`,{children:`After 70 generations of population-based evolution selecting for specimens that have a neuron count closest to 200 and minimize neuron death, we see that one of the surviving members displays stable waves of cell division. The neurons undergo mitosis until the population is approximately 200, at which point they cease. We can see variable strength connections forming, but there is no evolutionary pressure related to signal patterns in this case.`}),(0,h.jsx)(`div`,{style:{paddingBottom:`40px`},children:(0,h.jsxs)(a,{children:[s((0,h.jsx)(`img`,{width:`50%`,src:`project/neural-evolution-v1/neural-evolution-specimen.gif`})),s((0,h.jsx)(`img`,{width:`100%`,src:`project/neural-evolution-v1/neural-evolution-specimen.gif`}))]})})]})},{legacy:!1,id:`rums-composition`,title:`Robot Utility Models Policy Composition`,date:`2025-05-02`,status:`COMPLETED`,technologies:[`Python`,`Vector-Quantized Behavior Transformer`,`Robotics`,`Stretch`],page:e=>(0,h.jsxs)(`div`,{children:[(0,h.jsx)(`h4`,{children:`Description`}),(0,h.jsxs)(`p`,{children:[(0,h.jsx)(`i`,{children:`Robot Utility Models`}),` (RUMs) is a framework for training two-finger gripper manipulation policies with behavior cloning for the `,(0,h.jsx)(`i`,{children:`hello robot`}),` Stretch 3. The framework includes a hand-operated gripper tool for collecting demonstrations. The gripper tool is mounted with an iPhone that tracks odometry and camera feed data that can be transformed into positional and visual information matching that sensed from the robot's perspective. Data can be collected quickly by human operators with cheap equipment, instead of through teleoperation. We aim to augment the capabilities of the RUMs framework by implementing the composition of more granular policies.`]}),(0,h.jsx)(`h4`,{children:`Trained Policies`}),(0,h.jsxs)(`p`,{children:[`We first select tasks to compose.`,(0,h.jsxs)(`ol`,{children:[(0,h.jsx)(`li`,{children:`Picking up a lemon or lime.`}),(0,h.jsx)(`li`,{children:`Sorting a grasped lemon or lime to a left or right bowl, respectively.`})]}),`These policies should be deployed in sequence automatically based on the visual context. The sorting task serves the additional purpose of explicitly testing RUMs' handling of multi-modal tasks. In order to determine which policy should be deployed at what time, we have two strategic options:`,(0,h.jsxs)(`ol`,{children:[(0,h.jsx)(`li`,{children:`Compare the camera's current view to the aggregated visual embeddings of the start frames of policies.`}),(0,h.jsx)(`li`,{children:`Query a VLM for agentic decision-making.`})]}),`The composition of the pickup and sorting tasks appears as follows:`]}),(0,h.jsx)(`div`,{style:{paddingBottom:`40px`},children:(0,h.jsxs)(a,{children:[s((0,h.jsx)(`img`,{width:`50%`,src:`project/rums-composition/sort-lemon-rollout.gif`})),s((0,h.jsx)(`img`,{width:`100%`,src:`project/rums-composition/sort-lemon-rollout.gif`}))]})}),(0,h.jsxs)(`p`,{children:[`We trained these two policies on ~2000 demonstrations we collected in dozens of different environments. Descriptions of all demonstrations taken are included in this `,(0,h.jsx)(`a`,{href:`https://docs.google.com/document/d/1_k5rXlnYaIyyZ88u09NWMHRH34gcvnUyQs-CzBLu2FE/edit?usp=sharing`,children:`Task Data Descriptions`}),` document.`]}),(0,h.jsx)(`p`,{children:`We also tried a variant of the sorting task where lemons and limes were not necessary sorted left and right, but into a bowl with a physical label the color of the fruit. To reduce the data collection overhead, I 3D-printed the labels with ARUCO fiducial patterns with the intent to double our effective sample size in post-processing. I created one version of a given sample with the target bowl labeled yellow, and another version where the lemon was color-shifted green and the target bowl labeled green.`}),(0,h.jsx)(`div`,{style:{paddingBottom:`40px`},children:(0,h.jsxs)(a,{children:[s((0,h.jsxs)(h.Fragment,{children:[(0,h.jsx)(`img`,{width:`30%`,src:`project/rums-composition/fiducial-raw.gif`}),(0,h.jsx)(`img`,{width:`30%`,src:`project/rums-composition/fiducial-lemon.gif`}),(0,h.jsx)(`img`,{width:`30%`,src:`project/rums-composition/fiducial-lime.gif`})]})),(0,h.jsxs)(h.Fragment,{children:[s((0,h.jsx)(`img`,{width:`100%`,src:`project/rums-composition/fiducial-raw.gif`})),s((0,h.jsx)(`img`,{width:`100%`,src:`project/rums-composition/fiducial-lemon.gif`})),s((0,h.jsx)(`img`,{width:`100%`,src:`project/rums-composition/fiducial-lime.gif`}))]})]})}),(0,h.jsx)(`h4`,{children:`Alignment`}),(0,h.jsx)(`p`,{children:`Finally, I implemented an automatic pre-deployment alignment function that works by searching the surroundings for the view angle that looks most like a target image.`}),(0,h.jsx)(`div`,{style:{paddingBottom:`40px`},children:(0,h.jsxs)(a,{children:[s((0,h.jsx)(`img`,{width:`50%`,src:`project/rums-composition/rums-alignment.gif`})),s((0,h.jsx)(`img`,{width:`100%`,src:`project/rums-composition/rums-alignment`}))]})})]})},{legacy:!1,id:`programmatic-midi`,repository:`https://github.com/jaron-cui/midi-generator`,title:`Programmatic MIDI Generator`,date:`2024-10-03`,status:`COMPLETED`,technologies:[`Python`,`MIDI`,`PyTorch`,`Transformer`,`REMI`],page:e=>(0,h.jsxs)(`div`,{children:[(0,h.jsx)(`h4`,{children:`Samples`}),(0,h.jsx)(`p`,{children:`A couple of interesting outputs from the algorithm:`}),(0,h.jsx)(`h6`,{children:`Bright groove:`}),(0,h.jsx)(`audio`,{controls:!0,src:`project/programmatic-midi/bright_hectic.mp3`,children:`Audio not supported by browser`}),(0,h.jsx)(`h6`,{children:`Down in the caves (my favorite):`}),(0,h.jsx)(`audio`,{controls:!0,src:`project/programmatic-midi/down_in_the_caves.mp3`,children:`Audio not supported by browser`}),(0,h.jsx)(`h6`,{children:`Chicken coop chase:`}),(0,h.jsx)(`audio`,{controls:!0,src:`project/programmatic-midi/chicken_coop_chase.mp3`,children:`Audio not supported by browser`}),(0,h.jsx)(`h6`,{children:`The passing eons:`}),(0,h.jsx)(`audio`,{controls:!0,src:`project/programmatic-midi/calm_inquisitive.mp3`,children:`Audio not supported by browser`}),(0,h.jsx)(`h4`,{children:`Description`}),(0,h.jsx)(`p`,{children:`Music, as any art, comes from the heart.`}),(0,h.jsx)(`p`,{children:`But my calling as a computer scientist in 2024 compels me to automate away human artisans with cold, unfeeling machines. My ultimate objective is to exacerbate wealth inequality as large employment sectors of middle-income workers are replaced by a smaller class of higher-paid engineers.`}),(0,h.jsx)(`p`,{children:`Anyway, I thought it would be interesting to try my hand at generating piano music completely programmatically. Music is composed at a human's discretion. Great music is often described as closely following music theory rules, but breaking them a few times to bring out exceptional sound. Well... I think that musicians should just analyze those rule breaks and figure out the pattern so they can be added to the book of music theory.`}),(0,h.jsx)(`p`,{children:`The point is that most music follows well-known patterns. Surprisingly, there don't seem to be many easily accessible and good attempts at making programmatic music generators online. I would have thought someone would have done it in the 1980s or something.`}),(0,h.jsx)(`h4`,{children:`Properties of Good Music`}),(0,h.jsxs)(`p`,{children:[`I've written a concise list of general properties of good-sounding music.`,(0,h.jsxs)(`ol`,{children:[(0,h.jsx)(`li`,{children:`Harmonic consistency - adherence to a musical key, chord progressions, and the emphasis of chord notes.`}),(0,h.jsx)(`li`,{children:`Temporal consistency - inertia in changes of pitch or rhythm (scales and arpeggios versus random notes in the key).`}),(0,h.jsx)(`li`,{children:`Music Motifs - controlled repetition of ideas, borrowing of low-level musical structures.`}),(0,h.jsx)(`li`,{children:`Broad structure - distinct sections combined and modified to form a piece (like rhyme schemes, sections may be repeated. e.g. ABACA)/`})]})]}),(0,h.jsx)(`h4`,{children:`Incorporating Music Theory Algorithmically`}),(0,h.jsx)(`p`,{children:(0,h.jsxs)(`ul`,{children:[(0,h.jsx)(`li`,{children:`Top left: starting out with a single generic block`}),(0,h.jsx)(`li`,{children:`Top right: recursively subdividing the block`}),(0,h.jsx)(`li`,{children:`Bottom left: filling in concrete melodies and rhythms`}),(0,h.jsx)(`li`,{children:`Bottom right: borrowing from the pool of existing concrete melodies and rhythms`})]})}),(0,h.jsx)(`div`,{style:{paddingBottom:`40px`},children:(0,h.jsxs)(a,{children:[s((0,h.jsx)(`img`,{width:`80%`,src:`project/programmatic-midi/iterative-process.png`})),s((0,h.jsx)(`img`,{width:`100%`,src:`project/programmatic-midi/iterative-process.png`}))]})}),(0,h.jsx)(`p`,{children:`In summary, music is structured at several different scales and is defined by regular patterns. One crucial observation about music is that phrases can be broken up into smaller units, and those units are often interchangeable with similar alternatives. A useful simplification we derive from this observation is the representation of a given length of music as simply a (start_note, end_note, duration, chord_progression) unit. The most important notes in a given isolated musical chunk are the first and last note. We can recursively break this chunk into subchunks specified similarly, until we get to the scale of a few notes per chunk. Therefore, when generating a new piece, we first select the high-level details, such as the average tempo, chord progressions, and key. Then, we can perform the recursive subdivision process and build detail top-down.`}),(0,h.jsx)(`p`,{children:`In order to maintain harmonic and temporal consistency, we fill in the chunks between start and end notes with a graph search. The nodes of the graph are notes, and the edges are the intervals between consecutive notes. It is simple to apply constraints to satisfy the aforementioned consistencies. We simply cull all nodes that don't match the chord progression at a given time, and cull all edges that break interval rules. Then, a probabilistic graph search is an elegant solution.`}),(0,h.jsx)(`p`,{children:`As we fill in blocks, we end up with concrete melodies and rhythms. To satisfy the idea of motifs, we can play a clever trick where future block fills start looking at the pool of previously generated patterns and preferentially borrow compatible rhythms and melodies.`}),(0,h.jsx)(`p`,{children:`Finally, broad rearrangement can give us familiar section patterns. After doing some research, I've compiled a list of common section patterns that we sample from.`}),(0,h.jsx)(`div`,{style:{paddingBottom:`40px`},children:(0,h.jsxs)(a,{children:[s((0,h.jsx)(`img`,{width:`80%`,src:`project/programmatic-midi/section-patterns.png`})),s((0,h.jsx)(`img`,{width:`100%`,src:`project/programmatic-midi/section-patterns.png`}))]})}),(0,h.jsx)(`h4`,{children:`Conclusion`}),(0,h.jsxs)(`p`,{children:[`The final programmatic music generator outputs satisfactory results. However, there do exist unfavorable generations. Supplementing real training data with synthetic training data generated by this algorithm did not have a significant qualitatively observable impact on the music generated by a Transformer-XL architecture. The code for the model is available at `,(0,h.jsx)(`a`,{children:`https://github.com/vm2781/remi`}),`.`]})]})},{legacy:!1,id:`clockwork-robotic-arm`,title:`Clockwork Robotic Arm`,date:`2025-02-16`,status:`ON_HOLD`,technologies:[`CAD`,`Fusion360`,`Robotics`],page:e=>(0,h.jsxs)(`div`,{children:[(0,h.jsx)(`h4`,{children:`Description`}),(0,h.jsx)(`p`,{children:`3D printing is incredible, and gears are fun. I was mulling over my sore lack of a personal robotic arm on which to conduct machine learning experiments, and then thought of making my own. But then came to mind the hassle of electronics. Why not just skip the electronics?`}),(0,h.jsx)(`p`,{children:`Clockwork is fascinating to look at. An escapement mechanism allows for controlled releases of energy from some stored potential energy source - typically gravity or a spring. So, let's try building a fully mechanical yet programmable robotic arm.`}),(0,h.jsx)(`p`,{children:`The basic idea I have is that the arm's movements will occur in ticks, just like a clock. An escapement will regularly progress the arm's movement. We can manually control the movement of the arm by pulling levers that redirect mechanical power through different gears. If we can do that, then we can write simple programs consisting of lists of instructions that are fed through a conversion unit. Punch cards sure would be dandy.`}),(0,h.jsx)(`p`,{children:`The more difficult and tedious part than wishful brainstorming is the actual engineering of the mechanism. One feature I'd like is unlimited rotation of joints where physically allowed. Many electromechanical robotic arms have rotation limits because the wires hidden inside will twist. You can get around this using concentric conductive rings where electrical connections ride a shuttle around to avoid wire twist. I'd like to make a gear-based version of this concept.`}),(0,h.jsx)(`p`,{children:`Here, I sketch out concept drawings for the arm, and begin printing parts for the base joint.`}),(0,h.jsx)(`div`,{style:{paddingBottom:`40px`},children:(0,h.jsxs)(a,{children:[s((0,h.jsxs)(h.Fragment,{children:[(0,h.jsx)(`img`,{width:`30%`,src:`project/clockwork-robotic-arm/sketch1.jpg`}),(0,h.jsx)(`img`,{width:`30%`,src:`project/clockwork-robotic-arm/parts.jpg`})]})),s((0,h.jsxs)(h.Fragment,{children:[(0,h.jsx)(`img`,{width:`50%`,src:`project/clockwork-robotic-arm/sketch1.jpg`}),(0,h.jsx)(`img`,{width:`50%`,src:`project/clockwork-robotic-arm/parts.jpg`})]}))]})}),(0,h.jsx)(`p`,{children:`I then spent days designing a mechanical version of the concentric conductive twist joint power transmissions. The pictured mechanism should be capable of transferring 4 independent power chains up the arm to other joints.`}),(0,h.jsx)(`div`,{style:{paddingBottom:`40px`},children:(0,h.jsxs)(a,{children:[s((0,h.jsx)(`img`,{width:`30%`,src:`project/clockwork-robotic-arm/cad.png`})),s((0,h.jsx)(`img`,{width:`30%`,src:`project/clockwork-robotic-arm/cad.png`}))]})}),(0,h.jsx)(`h4`,{children:`Project on Hold`}),(0,h.jsx)(`p`,{children:`I have become busy with research at GRAIL and other projects, so this will have to wait for the foreseeable future.`})]})},{legacy:!1,id:`chess`,repository:`https://github.com/jaron-cui/jaron-cui.github.io/tree/master/src/page/extraneous/chess`,title:`Chess`,date:`2024-02-10`,status:`ON_HOLD`,technologies:[`TypeScript`,`PixiJS`],page:e=>(0,h.jsxs)(`div`,{children:[(0,h.jsx)(`h4`,{children:`Preview`}),`Here is a snapshot of progress on the project. Visit `,(0,h.jsx)(`a`,{href:`https://jaron-cui.github.io/#/chess`,children:`https://jaron-cui.github.io/#/chess`}),` for the latest version.`,(0,h.jsx)(t,{}),(0,h.jsx)(`h4`,{children:`Info`}),(0,h.jsx)(`p`,{children:`This is my attempt at efficiently implementing chess! There are a few things we want to be able to do:`}),(0,h.jsxs)(`ul`,{children:[(0,h.jsx)(`li`,{children:`Determine legal moves`}),(0,h.jsx)(`li`,{children:`Indicate to the player all their currently allowed moves`})]}),(0,h.jsx)(`p`,{children:`The approach I decided to take was one where we maximally cache information regarding potential moves. Every square on the board keeps a list of coordinates from which pieces can move to it and a list of coordinates that should recalculate possible moves if the square is updated.`}),(0,h.jsx)(`p`,{children:`For example, a rook, which can move in a straight line of any length, will be obstructed by pieces in its path. All the squares which it can currently move to will store its position. Squares in the rook's path which hold a piece will also store its position, but tagged as 'If this square changes, check with me!'.`}),(0,h.jsx)(`p`,{children:`This approach avoids recalculating every possible move after every turn, making it fast and straightforward to tell where pieces can move.`})]})},{legacy:!1,id:`rect`,repository:`https://github.com/jaron-cui/jaron-cui.github.io/tree/master/src/page/extraneous/rect`,title:`Get Rect Remastered`,date:`2024-01-04`,status:`ACTIVE`,technologies:[`TypeScript`,`PixiJS`,`WebGL`],features:[`Physics`,`Graphics`],page:e=>(0,h.jsxs)(`div`,{children:[(0,h.jsx)(`h4`,{children:`Features`}),(0,h.jsx)(`ul`,{children:[`Custom 2D physics engine`,`WebGL shader terrain rendering`,`Platformer movement`].map(e=>(0,h.jsx)(`li`,{children:e}))}),(0,h.jsx)(`h4`,{children:`Preview`}),(0,h.jsx)(`p`,{children:`Try using WASD to control the player!`}),(0,h.jsxs)(`p`,{children:[`Visit `,(0,h.jsx)(`a`,{href:`https://jaron-cui.github.io/#/rect`,children:`https://jaron-cui.github.io/#/rect`}),` for the latest version.`]}),(0,h.jsx)(n,{}),(0,h.jsx)(`h4`,{children:`Description`}),(0,h.jsx)(`p`,{children:`This is an attempt to recreate the first game I made, "get_rect()".`}),(0,h.jsx)(`p`,{children:`The original game was PVP with destructible tiled terrain. There were numerous weapons and props at the player's disposal.`}),(0,h.jsx)(`p`,{children:`It was multiplayer in the sense that two players would control their avatars from the same device, one using WASD, and the other using the arrow keys.`}),(0,h.jsx)(`p`,{children:`Fireworks, TNT, bow & arrows, swords, throwable logs were acquirable by parachuted crates falling from the sky.`}),(0,h.jsx)(`p`,{children:`Being the first game I had created, the physics were simplistically and not so carefully crafted. The implementations were incredible far from optimal. One early mistake I made was loading each block texture from file for every single block on the screen, every frame.`}),(0,h.jsx)(`p`,{children:`This new version will use the arsenal of programming skills and mathematical knowledge I've gained since high school to build a better, faster, and even more fun online multiplayer game in the same spirit.`})]})},{legacy:!1,id:`robotic-hand`,title:`Robotic Hand`,date:`2024-02-01`,status:`COMPLETED`,repository:`https://github.com/jaron-cui/robotic-hand`,technologies:[`Python`,`3D Printing`,`CAD`,`Computer Aided Design`,`Fusion360`,`Blender`],page:e=>(0,h.jsxs)(`div`,{children:[(0,h.jsx)(`div`,{style:{paddingBottom:`40px`},children:(0,h.jsxs)(a,{children:[s((0,h.jsx)(`img`,{width:`30%`,src:`project/robot-hand/robot-hand-side.jpg`})),s((0,h.jsx)(`img`,{width:`100%`,src:`project/robot-hand/robot-hand-side.jpg`}))]})}),(0,h.jsxs)(`div`,{style:{paddingBottom:`40px`},children:[(0,h.jsx)(`h4`,{children:`Description`}),(0,h.jsxs)(`p`,{children:[`Have you ever chased the warmth of friendship and comraderie? The joy of recalling fond memories involving shared experiences? We should feel grateful to have been granted existence, for these pleasures are precious `,(0,h.jsx)(`i`,{children:`because`}),` they are few and fleeting. Only the living can take the mundane for granted.`]}),(0,h.jsxs)(`p`,{children:[`...but what if instead, you had a cool robotic arm to play games with you, no social interaction required?? That's precisely the thought I had in early 2024! With a 3D printer, CAD skills, and computer science, the possibilities are limited! I assembled a team to make this dream a reality. Bringing the firmware skills of `,(0,h.jsx)(`a`,{href:`https://www.linkedin.com/in/iyerraj/`,children:`Rajiv Iyer`}),` and the programming prowess of `,(0,h.jsx)(`a`,{href:`https://www.linkedin.com/in/eric-m-823937179/`,children:`Eric Ma`}),` onboard, we set out to build this thing from nothing.`]}),(0,h.jsx)(`p`,{children:`We settled on the concept of a robotic arm capable of spontaneously reciprocating games of rock-paper-scissors with passerby. The arm would constantly analyze a camera feed directed at its engagement zone for human hands performing the characteristic downward swings of a game-seeking fist. Then, the arm would anticipate and match the motion for 3 swings while chanting "rock, paper, SCISSORS!" before throwing a move and responding to the outcome of the match. A word of warning: this robot is NOT sportsmanlike.`}),(0,h.jsx)(`p`,{children:`We delegated 3 objectives between me (1), Rajiv (2), and Eric (3):`}),(0,h.jsxs)(`ol`,{children:[(0,h.jsx)(`li`,{children:`Design, fabricate the parts of, and physically construct the robotic arm`}),(0,h.jsx)(`li`,{children:`Implement firmware for controlling the robotic arm from a computer`}),(0,h.jsx)(`li`,{children:`Implement AI for directing the behavior of the robotic arm`})]}),(0,h.jsx)(`p`,{children:`We were able to successfully complete these objectives in loose parallel, and you can see the results of our work below.`}),(0,h.jsx)(g,{link:`https://youtube.com/embed/By0YNmuQ91c?playlist=By0YNmuQ91c&loop=1`})]}),(0,h.jsxs)(`div`,{style:{paddingBottom:`40px`},children:[(0,h.jsx)(`h4`,{children:`Constructing the Robot`}),(0,h.jsx)(`h5`,{children:`Proof of Concept`}),(0,h.jsx)(`p`,{children:`Initially, I aimed to build some sort of robot using multiple joints. However, placing a motor at each joint would be a major limiting factor. Motors need wiring and can be heavy! So, I decided to take inspiration from biological muscles and attempt to use tension to actuate segments around a jointed skeleton. This would allow the motors to be mounted in a more centralized and secure location instead of at the joints. The proof of concept was a bulky and rough hinged mechanism held straight with a spring and pulled shut with a cable. (The spring was a rubber band and the cable was dental floss...)`}),(0,h.jsx)(`p`,{children:`Once this worked, I quickly iterated to refining a single finger and then incorporating multiple into a hand. The viability of the mechanism led me to decide on the direction based around a robotic hand.`}),(0,h.jsx)(v,{media:[{type:`image`,link:`project/robot-hand/robot-hand-finger-prototype.gif`,description:`Proof-of-concept`},{type:`image`,link:`project/robot-hand/robot-hand-finger-comparison.jpg`,description:`Refining finger to improve maximum retraction`},{type:`image`,link:`project/robot-hand/robot-hand.gif`,description:`Integrating fingers into a single palm`}]}),(0,h.jsx)(`h5`,{children:`Arm Structure`}),(0,h.jsx)(`p`,{children:`There are two main types expressive motions required for rock-paper-scissors - hand gestures and arm movement. We have the hand with individually movable fingers, so next comes an arm. A forearm is sufficient, as the ritual for starting a game simply involves bobbing a fist rhythmically. But how do we communicate tension from the motors to the hand if between them lies an arm? We can run cables down the arm. But another problem - if we run the cables on top of or under the arm, then the cables could be stretched or relaxed by arm rotation even if the motors for the fingers are stationary. This is no good - we don't want the hand gesture to change due to arm movement. But this does not happen if the cables run through the arm's axis of rotation.`}),(0,h.jsx)(`p`,{children:`For these reasons, cables run through guides down the center of the forearm into a guide mounted on the base plate. The guide mounted on the base plate is fitted to rotate freely to minimize the cable displacement caused by arm rotation. Cables go through this guide and then down below the base plates to where the motors will eventually reside.`}),(0,h.jsx)(v,{media:[{type:`image`,link:`project/robot-hand/robot-hand-arm-sketch.jpg`,description:`Rough design sketch`},{type:`image`,link:`project/robot-hand/robot-hand-mounted-guide.jpg`,description:`The freely rotating base-plate mounted cable guide`},{type:`image`,link:`project/robot-hand/robot-hand-unmotorized-arm.jpg`,description:`The arm installed on base plate with threaded cables`}]}),(0,h.jsx)(`h5`,{children:`Motorization`}),(0,h.jsxs)(`p`,{children:[`Next came the motorization of these mechanisms. I decided to use the small and cheap `,(0,h.jsx)(`a`,{href:`https://www.mouser.com/datasheet/2/758/stepd-01-data-sheet-1143075.pdf`,children:`28BYJ-48 – 5V Stepper Motor`}),`. Since the finger retraction is tension-based and may required tuning, it seems logical to use a winch made of swappable parts that can be calibrated physically with adjustments to the gears and have its range tweaked in code. For the elbow, we can just have the motor's axle angle be proportional to the arm's rotation angle.`]}),(0,h.jsx)(`p`,{children:`I specifically designed the winch's spool gear meshed with the driving gear as a partial gear (it has a section without teeth). This is so that any mistakes in the control programming won't put cables under critical tension in the event that the motor over-retracts. It is easier to amend code than it is to replace snapped parts. For reference, each of the three segments in a single finger may take around 40 minutes to print, and the tiny bolts used in the hinges between them take 8 minutes. The largest part in the robot took 5-6 hours to print.`}),(0,h.jsx)(v,{media:[{type:`image`,link:`project/robot-hand/robot-hand-finger-winch.jpg`,description:`The motorized winch for controlling finger retraction`},{type:`image`,link:`project/robot-hand/robot-hand-elbow-motor.jpg`,description:`The motor mount for controlling arm rotation`}]}),(0,h.jsx)(`p`,{children:`I decided to attach a lead cable ending with an alligator clip to the finger winches for convenient coupling/decoupling with the finger cables. This is useful for when the base plate needs to be remove for maintenance and for fine-tuning cable tensions. Below, see the positioning of the finger winches in a compartment below the base plate and the situation of the elbow motor on top of the base plate.`}),(0,h.jsx)(v,{media:[{type:`image`,link:`project/robot-hand/robot-hand-finger-winch-positioning.jpg`,description:`The motorized finger winches live under the base plate`},{type:`image`,link:`project/robot-hand/robot-hand-finger-winch-mounted.jpg`,description:`A motorized winch hooked up to the corresponding finger cable`},{type:`image`,link:`project/robot-hand/robot-hand-elbow-motor-meshing.jpg`,description:`The motor mount for controlling arm rotation`}]}),(0,h.jsx)(`h5`,{children:`Control`}),(0,h.jsxs)(`p`,{children:[`Finally, now that the methods of actuation and motorization are established, we move on to the control hardware. Since the robot's AI will require rapid image processing, it makes sense for it to live on a performant personal computer rather than an onboard processing unit. So, we will use lightweight controllers that simply receive commands from a device via serial connection. We chose to use the `,(0,h.jsx)(`a`,{href:`https://docs.espressif.com/projects/esp-idf/en/latest/esp32s3/hw-reference/esp32s3/user-guide-devkitm-1.html`,children:`ESP-32S Development Board`}),` as a microcontroller. Here is what the guts of the robot looked like after installing all finger winches, cable guides, wiring, and controllers.`]}),(0,h.jsxs)(a,{children:[s((0,h.jsxs)(h.Fragment,{children:[(0,h.jsx)(`img`,{width:`30%`,src:`project/robot-hand/robot-hand-guts.jpg`}),(0,h.jsx)(`img`,{width:`30%`,src:`project/robot-hand/robot-hand-guts2.jpg`})]})),(0,h.jsxs)(h.Fragment,{children:[s((0,h.jsx)(`img`,{width:`100%`,src:`project/robot-hand/robot-hand-guts.jpg`})),s((0,h.jsx)(`img`,{width:`100%`,src:`project/robot-hand/robot-hand-guts2.jpg`}))]})]})]}),(0,h.jsxs)(`div`,{style:{paddingBottom:`40px`},children:[(0,h.jsx)(`h4`,{children:`Software/AI`}),(0,h.jsx)(`h5`,{children:`Detecting Game Start Ritual`}),(0,h.jsx)(`p`,{children:`The game start ritual between humans involves making a fist, extending the arm outward, and then rhythmically swinging down three times before switching to a move gesture on the final swing. We can simplify the tracking of this procedure by replacing arm movement with the stand-in metric of hand position. If a hand is bobbing up and down, we will interpret this as the arm bobbing up and down. Even though it could be the camera moving or the entire human moving, for our purposes it is plausible enough to assume that an opponent is indeed offering a challenge.`}),(0,h.jsx)(`p`,{children:`Since we need to identify the hand to read its gesture anyway, this abstraction doubles as allowing the start ritual to be identified without requiring any additional computer vision computation. We can read the hand's y-position and record its evolution over time. By fitting the position to an oscillating function, we can detect the ritual, estimate the tempo of the movement, and reciprocate the motion. We chose to regress the data against a sine wave because of its simplicity. A function that more accurately reflects the assymetrical velocity of the arm between upwards and downwards swings could potentially improve the performance of this technique.`}),s((0,h.jsx)(`img`,{src:`project/robot-hand/robot-hand-initiate-graphic.png`})),(0,h.jsxs)(`h5`,{children:[`Perception `,(0,h.jsx)(`i`,{children:`(CREDIT: Section Authored by Eric Ma)`})]}),(0,h.jsx)(`p`,{children:(0,h.jsx)(`i`,{children:`Detection, landmarking, gesture recognition`})}),(0,h.jsxs)(`p`,{children:[`We started with a third-party model from Google's `,(0,h.jsx)(`a`,{href:`https://developers.google.com/mediapipe/solutions/vision/gesture_recognizer`,children:`MediaPipe`}),` as the basis for hand perception. This model is a combination of multiple, providing hand detection, hand landmarking, and gesture recognition, with support for live video. According to the model card, the landmarking portion uses a CNN, and gesture recognition uses fully connected networks to perform classification on an embedding of the landmarks. The model showed good performance for the prior two, but gesture recognition was unreliable for poses in rock-paper-scissors. We fine-tuned the model on these poses, and obtained much better results.`]}),(0,h.jsx)(`p`,{children:(0,h.jsx)(`i`,{children:`Position tracking`})}),(0,h.jsxs)(`p`,{children:[`The MediaPipe model provides landmarking and therefore tracking for the hand, but it's suboptimal when there's fast movement, and can drop frames during periods of heavy computation. To compensate for samples that may be missed for these reasons, we added a second tracker provided by OpenCV to serve as backup when needed. We settled on a filter based on `,(0,h.jsx)(`a`,{href:`https://arxiv.org/abs/1611.08461`,children:`Discriminative Correlation Filter with Channel and Spatial Reliability (CSRT)`}),`, which showed the best results for this particular purpose, even when rate-limited due to its performance cost.`]}),(0,h.jsx)(`h5`,{children:`State Machine`}),(0,h.jsx)(`p`,{children:`By constantly visually monitoring the engagement region, the robot can detect when a game has started and act on it. The robot's behavior is elegantly described by a state machine.`}),s((0,h.jsx)(`img`,{src:`project/robot-hand/robot-hand-state-machine.jpg`})),(0,h.jsx)(`label`,{children:`State Machine Diagram Credit: Eric Ma, Rajiv Iyer, Jaron Cui`})]}),(0,h.jsxs)(`div`,{style:{paddingBottom:`40px`},children:[(0,h.jsx)(`h4`,{children:`Afterword`}),(0,h.jsx)(`p`,{children:`This concludes the journey of developing the arm. I learned a lot from the project, first and foremost that the 28BYJ-48 stepper motor is VERY WEAK. So many headaches having to do with the sheer lack of power these things can exert. And when they do exert force towards their upper limit, they heat up so much that they melt the PLA I used to print the gears and motor mounts. I will definitely keep this in mind for future projects, and I may revisit the concept of robotic arms with a trove of experience. This was the first robot I've ever built, so I'm certain I can do much better!`}),(0,h.jsx)(`p`,{children:`Thank you for reading until the end. It took a long time to write. Like 4hrs. See you!`})]})]})}],x=[...p.map(e=>({legacy:!0,...e})),...b],S={};x.forEach(e=>S[e.id]=e);var C=S,w=m;export{g as a,v as i,x as n,C as r,w as t};